Here is the commit message:
selftests/x86/mov_ss_trap: Fix the SYSENTER test

For reasons that I haven't quite fully diagnosed, running
mov_ss_trap_32 on a 32-bit kernel results in an infinite loop in
userspace.  This appears to be because the hacky SYSENTER test
doesn't segfault as desired; instead it corrupts the program state
such that it infinite loops.

Fix it by explicitly clearing EBP before doing SYSENTER.  This will
give a more reliable segfault.

Fixes: 59c2a7226fc5 ("x86/selftests: Add mov_to_ss test")
Signed-off-by: Andy Lutomirski <luto@kernel.org>
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Cc: stable@kernel.org

Here is the root cause:
The bug was caused by the SYSENTER test not triggering a segmentation fault as expected, which led to corruption of the program state and resulted in an infinite loop in userspace. This issue arose because the EBP register was not cleared prior to executing the SYSENTER instruction, causing unpredictable behavior in the test.

Here is the patch:

 int main()
 {
 	unsigned long nr;

 	asm volatile ("mov %%ss, %[ss]" : [ss] "=m" (ss));
 	printf("\tSS = 0x%hx, &SS = 0x%p\n", ss, &ss);

 	if (prctl(PR_SET_PTRACER, PR_SET_PTRACER_ANY, 0, 0, 0) == 0)
 		printf("\tPR_SET_PTRACER_ANY succeeded\n");

 	printf("\tSet up a watchpoint\n");
 	sethandler(SIGTRAP, sigtrap, 0);
 	enable_watchpoint();

 	printf("[RUN]\tRead from watched memory (should get SIGTRAP)\n");
 	asm volatile ("mov %[ss], %[tmp]" : [tmp] "=r" (nr) : [ss] "m" (ss));

 	printf("[RUN]\tMOV SS; INT3\n");
 	asm volatile ("mov %[ss], %%ss; int3" :: [ss] "m" (ss));

 	printf("[RUN]\tMOV SS; INT 3\n");
 	asm volatile ("mov %[ss], %%ss; .byte 0xcd, 0x3" :: [ss] "m" (ss));

 	printf("[RUN]\tMOV SS; CS CS INT3\n");
 	asm volatile ("mov %[ss], %%ss; .byte 0x2e, 0x2e; int3" :: [ss] "m" (ss));

 	printf("[RUN]\tMOV SS; CSx14 INT3\n");
 	asm volatile ("mov %[ss], %%ss; .fill 14,1,0x2e; int3" :: [ss] "m" (ss));

 	printf("[RUN]\tMOV SS; INT 4\n");
 	sethandler(SIGSEGV, handle_and_return, SA_RESETHAND);
 	asm volatile ("mov %[ss], %%ss; int $4" :: [ss] "m" (ss));

 #ifdef __i386__
 	printf("[RUN]\tMOV SS; INTO\n");
 	sethandler(SIGSEGV, handle_and_return, SA_RESETHAND);
 	nr = -1;
 	asm volatile ("add $1, %[tmp]; mov %[ss], %%ss; into"
 		      : [tmp] "+r" (nr) : [ss] "m" (ss));
 #endif

 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; ICEBP\n");

 		/* Some emulators (e.g. QEMU TCG) don't emulate ICEBP. */
 		sethandler(SIGILL, handle_and_longjmp, SA_RESETHAND);

 		asm volatile ("mov %[ss], %%ss; .byte 0xf1" :: [ss] "m" (ss));
 	}

 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; CLI\n");
 		sethandler(SIGSEGV, handle_and_longjmp, SA_RESETHAND);
 		asm volatile ("mov %[ss], %%ss; cli" :: [ss] "m" (ss));
 	}

 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; #PF\n");
 		sethandler(SIGSEGV, handle_and_longjmp, SA_RESETHAND);
 		asm volatile ("mov %[ss], %%ss; mov (-1), %[tmp]"
 			      : [tmp] "=r" (nr) : [ss] "m" (ss));
 	}

 	/*
 	 * INT $1: if #DB has DPL=3 and there isn't special handling,
 	 * then the kernel will die.
 	 */
 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; INT 1\n");
 		sethandler(SIGSEGV, handle_and_longjmp, SA_RESETHAND);
 		asm volatile ("mov %[ss], %%ss; int $1" :: [ss] "m" (ss));
 	}

 #ifdef __x86_64__
 	/*
 	 * In principle, we should test 32-bit SYSCALL as well, but
 	 * the calling convention is so unpredictable that it's
 	 * not obviously worth the effort.
 	 */
 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; SYSCALL\n");
 		sethandler(SIGILL, handle_and_longjmp, SA_RESETHAND);
 		nr = SYS_getpid;
 		/*
 		 * Toggle the high bit of RSP to make it noncanonical to
 		 * strengthen this test on non-SMAP systems.
 		 */
 		asm volatile ("btc $63, %%rsp\n\t"
 			      "mov %[ss], %%ss; syscall\n\t"
 			      "btc $63, %%rsp"
 			      : "+a" (nr) : [ss] "m" (ss)
 			      : "rcx"
 #ifdef __x86_64__
 				, "r11"
 #endif
 			);
 	}
 #endif

 	printf("[RUN]\tMOV SS; breakpointed NOP\n");
 	asm volatile ("mov %[ss], %%ss; breakpoint_insn: nop" :: [ss] "m" (ss));

 	/*
 	 * Invoking SYSENTER directly breaks all the rules.  Just handle
 	 * the SIGSEGV.
 	 */
 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; SYSENTER\n");
 		stack_t stack = {
 			.ss_sp = altstack_data,
 			.ss_size = SIGSTKSZ,
 		};
 		if (sigaltstack(&stack, NULL) != 0)
 			err(1, "sigaltstack");
 		sethandler(SIGSEGV, handle_and_longjmp, SA_RESETHAND | SA_ONSTACK);
 		nr = SYS_getpid;
-		asm volatile ("mov %[ss], %%ss; SYSENTER" : "+a" (nr)
+		/* Clear EBP first to make sure we segfault cleanly. */
+		asm volatile ("xorl %%ebp, %%ebp; mov %[ss], %%ss; SYSENTER" : "+a" (nr)
 			      : [ss] "m" (ss) : "flags", "rcx"
 #ifdef __x86_64__
 				, "r11"
 #endif
 			);

 		/* We're unreachable here.  SYSENTER forgets RIP. */
 	}

 	if (sigsetjmp(jmpbuf, 1) == 0) {
 		printf("[RUN]\tMOV SS; INT $0x80\n");
 		sethandler(SIGSEGV, handle_and_longjmp, SA_RESETHAND);
 		nr = 20;	/* compat getpid */
 		asm volatile ("mov %[ss], %%ss; int $0x80"
 			      : "+a" (nr) : [ss] "m" (ss)
 			      : "flags"
 #ifdef __x86_64__
 				, "r8", "r9", "r10", "r11"
 #endif
 			);
 	}

 	printf("[OK]\tI aten't dead\n");
 	return 0;
 }
